pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        address oldOwner = c.owner();

        // Transfer ownership to caller to set up scenario
        vm.prank(oldOwner);
        c.transferOwnership(caller);

        // Ensure caller is now owner
        assertEq(c.owner(), caller);

        // Now caller calls owned()
        vm.prank(caller);
        c.owned();

        // After owned(), owner must equal caller (the one who called owned())
        assertTrue(c.owner() == caller);
    }
}

